head.script:
scwin.onpageload = function () {
	requires("uiplugin.popup");

};

scwin.trigger2_onclick = function (e) {
	var options = {
		id: "popup1",
		name: "popup1",
		type: "wframePopup",
		width: "800px",
		height: "400px",
		popupUrl: "popup_openPopup_popupAutoCloseSkip_WESE-1010_(WSQ-5881)_sub.xml",
		accessibility: true,
		useControl: "true",
		features: "noopener",
		controls: { minimize: false, maximize: false, close: true },
		popupAutoCloseSkip: true
	};
	$p.openPopup("", options);
};
